type Linha = { id: number; nome: string; versao: number };
const tabela = new Map<number, Linha>([[1, { id: 1, nome: 'Fornecedor A', versao: 7 }]]);

function atualiza(id: number, nome: string, versaoLida: number): number {
  const atual = tabela.get(id);
  if (!atual) return 404;
  if (atual.versao !== versaoLida) return 409; // UPDATE ... AND versao = :lida -> 0 linhas
  tabela.set(id, { id, nome, versao: atual.versao + 1 });
  return 200;
}

