type Banco = { pedidos: string[]; itens: string[] };
let banco: Banco = { pedidos: [], itens: [] };

function gravaItem(b: Banco, item: string) {
  if (item.endsWith('?')) throw new Error('item inválido');
  b.itens.push(item);
}

// Jeito 1: várias chamadas à API
banco.pedidos.push('P1');
for (const item of ['P1-a', 'P1-b?', 'P1-c']) {
  try { gravaItem(banco, item); } catch { break; } // a tela para no erro
}
console.log(JSON.stringify(banco));

// Jeito 2: uma chamada, uma transação
const tx: Banco = structuredClone(banco);
try {
  tx.pedidos.push('P2');
  for (const item of ['P2-a', 'P2-b?', 'P2-c']) gravaItem(tx, item);
  banco = tx; // commit
} catch { /* rollback: tx é descartado */ }
console.log(JSON.stringify(banco));

