import { EventEmitter } from 'node:events';

const eventos = new EventEmitter();
eventos.on('pedido.gravado', (id: number) => console.log(`e-mail enviado: pedido ${id}`));

function grava(id: number, commitFalha: boolean, emiteAntes: boolean) {
  try {
    if (emiteAntes) eventos.emit('pedido.gravado', id);
    if (commitFalha) throw new Error('ORA-02291');
    console.log(`pedido ${id}: commit`);
    if (!emiteAntes) eventos.emit('pedido.gravado', id);
  } catch {
    console.log(`pedido ${id}: rollback`);
  }
}

grava(1, true, true);
grava(2, true, false);
grava(3, false, false);

function debounce<T>(fn: (v: T) => void, ms: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return (v: T) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(v), ms);
  };
}

