const espera = (ms: number) => new Promise((r) => setTimeout(r, ms));
async function api(termo: string) {
  await espera(termo === 'al' ? 120 : 30);
  return `resultado de ${termo}`;
}

let naTela = '';
let ultima = 0;
async function buscaIngenua(termo: string) {
  naTela = await api(termo);
}
async function buscaSegura(termo: string) {
  const minha = ++ultima;
  const r = await api(termo);
  if (minha === ultima) naTela = r;
}

await Promise.all([buscaIngenua('al'), buscaIngenua('alfa')]);
console.log('ingênua:', naTela);
await Promise.all([buscaSegura('al'), buscaSegura('alfa')]);
