type Conexao = { clientId: string | null };
const pool: Conexao[] = [{ clientId: null }];
const auditoria: string[] = [];

function requisicao(usuario: string | null, acao: string, limpaAoDevolver: boolean) {
  const c = pool.pop()!;
  if (usuario) c.clientId = usuario; // quando é null, a rota não propagou
  auditoria.push(`${acao} por ${c.clientId ?? 'APP_SERVICO'}`);
  if (limpaAoDevolver) c.clientId = null;
  pool.push(c);
}

